package com.group01.assessment.infrastructure.persistence.adapter; import com.group01.assessment.domain.entity.ErrorAnalysisItem; import com.group01.assessment.domain.repository.ErrorAnalysisItemRepository; import com.group01.assessment.infrastructure.persistence.mapper.AssessmentPersistenceMapper; import com.group01.assessment.infrastructure.persistence.repository.ErrorAnalysisItemJpaRepository; import org.springframework.stereotype.Component; import java.util.*;
@Component public class ErrorAnalysisItemRepositoryAdapter implements ErrorAnalysisItemRepository{private final ErrorAnalysisItemJpaRepository repository;private final AssessmentPersistenceMapper mapper;public ErrorAnalysisItemRepositoryAdapter(ErrorAnalysisItemJpaRepository repository,AssessmentPersistenceMapper mapper){this.repository=repository;this.mapper=mapper;}public List<ErrorAnalysisItem> saveAll(List<ErrorAnalysisItem> v){return repository.saveAll(v.stream().map(mapper::toEntity).toList()).stream().map(mapper::toDomain).toList();}public List<ErrorAnalysisItem> findByResultId(UUID id){return repository.findByResultId(id).stream().map(mapper::toDomain).toList();}}
